package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.TrackedFlight;import com.makemytrip.makemytrip.repositories.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@Service public class FlightTrackingService{private final TrackedFlightRepository tracked;private final FlightRepository flights;public FlightTrackingService(TrackedFlightRepository t,FlightRepository f){tracked=t;flights=f;}public TrackedFlight track(String user,String flight){if(!flights.existsById(flight))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Flight not found");var existing=tracked.findByUserIdAndFlightId(user,flight);if(existing.isPresent())return existing.get();TrackedFlight t=new TrackedFlight();t.setUserId(user);t.setFlightId(flight);try{return tracked.save(t);}catch(DuplicateKeyException race){return tracked.findByUserIdAndFlightId(user,flight).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Flight tracking could not be saved"));}}public void untrack(String user,String flight){tracked.deleteByUserIdAndFlightId(user,flight);}public List<TrackedFlight> list(String user){return tracked.findByUserId(user);}}
